/*
 * Recorder for the temporary stretch and the SyQon/Studio exchange helpers:
 * expression strings (lib/StepsSyqon.js:418-458), the MTF helpers
 * (lib/StepsSyqon.js:983-991), the PRISM target selection
 * (lib/StepsSyqon.js:977-1145), studioDeclaredOutput (lib/StepsSyqon.js:2064-2075)
 * and the SyQon constants (lib/StepsSyqon.js:232-237).
 *
 * Synthetic images are generated by integer formulas that the Python suite
 * reproduces exactly, so only the recorded results are stored.
 */
"use strict";

module.exports = function( js )
{
   const { Steps } = js;

   // Util.log and Util.warn write through PJSR's console; node has no such methods, so they are silenced.
   for ( const k of [ "writeln", "warningln" ] ) if ( typeof console[k] !== "function" ) console[k] = () => {};

   // The fake images below ignore the rectangle; Rect only has to exist for the PRISM helpers' calls.
   const realRect = globalThis.Rect;
   globalThis.Rect = function Rect( x, y, w, h ) { this.x0 = x; this.y0 = y; this.x1 = x + w; this.y1 = y + h; };

   // A plain image object with the PixelMath/PixInsight accessors the PRISM helpers use.
   // planes[c][y][x]; median of the odd-count planes used here is the middle sorted value.
   function fakeImage( planes )
   {
      const h = planes[0].length, w = planes[0][0].length;
      const rows = ( c ) => planes[c];
      return {
         width: w,
         height: h,
         numberOfChannels: planes.length,
         sample( x, y, c ) { return rows( c )[y][x]; },
         minimum( rect, c0 ) {
            let m = Infinity;
            for ( const row of rows( c0 ) ) for ( const v of row ) if ( v < m ) m = v;
            return m;
         },
         median( rect, c0 ) {
            const all = [];
            for ( const row of rows( c0 ) ) for ( const v of row ) all.push( v );
            all.sort( ( a, b ) => a - b );
            const n = all.length;
            return n % 2 ? all[( n - 1 ) / 2] : ( all[n / 2 - 1] + all[n / 2] ) / 2;
         }
      };
   }

   // Integer-driven synthetic planes: the same formula is written in the Python test.
   function synth( w, h, nch, base, span, mod )
   {
      const out = [];
      for ( let c = 0; c < nch; ++c )
      {
         const p = [];
         for ( let y = 0; y < h; ++y )
         {
            const row = [];
            for ( let x = 0; x < w; ++x )
               row.push( ( ( x * 37 + y * 101 + c * 53 ) % mod ) / mod * span + base );
            p.push( row );
         }
         out.push( p );
      }
      return out;
   }

   const win = ( planes ) => ( { mainView: { image: fakeImage( planes ) } } );

   // studioDeclaredOutput reads File.exists: the shim's File is replaced for the calls, then restored.
   const existing = new Set( [ "/fake/out/a.xisf", "/fake/out/b.xisf", "/fake/out/c.fits" ] );
   const realExists = File.exists;
   File.exists = ( p ) => existing.has( p );
   let declared;
   try
   {
      declared = {
         last_existing: Steps.studioDeclaredOutput( "log\n/fake/out/a.xisf\n/fake/out/b.xisf\nbye\n" ),
         skips_missing: Steps.studioDeclaredOutput( "/fake/out/a.xisf\n/fake/out/missing.xisf\n" ),
         ignores_other_suffix: Steps.studioDeclaredOutput( "/fake/out/a.xisf\n/fake/out/c.fits\n" ),
         crlf: Steps.studioDeclaredOutput( "x\r\n/fake/out/b.xisf\r\n" ),
         none: Steps.studioDeclaredOutput( "nothing here\n" ),
         empty: Steps.studioDeclaredOutput( "" )
      };
   }
   finally
   {
      File.exists = realExists;
   }

   // The PixelMath pixel symbol is stored as {px}; the Python test maps it back.
   const px = ( list ) => list.map( s => s.split( "$" + "T" ).join( "{px}" ) );

   const mtfRows = [];
   for ( const [ x0, t ] of [ [ 0.05, 0.25 ], [ 0.0123, 0.12 ], [ 0.4, 0.7 ] ] )
      mtfRows.push( { x0, target: t, midtone: Steps.mtfMidtoneFor( x0, t ) } );
   const mtfApplied = [ [ 0.3, 0.2 ], [ 0.9, 0.05 ], [ 0.001, 0.4 ] ].map( ( [ m, x ] ) => ( { m, x, y: Steps.mtfApply( m, x ) } ) );

   const mins = [ 0, 1e-7, 0.0123456789, 0.00000762939453125, 0.5, 0.999999 ];
   const normalise = px( mins.map( m => Steps.syqonNormalizeExpression( format( "%.16f", m ) ) ) );
   const denormalise = px( mins.map( m => Steps.syqonDenormalizeExpression( format( "%.16f", m ) ) ) );
   const pairs = [ [ 0.1234567891234567, 0.12 ], [ 0.25, 0.5 ], [ 0.00762939453125, 0.12 ] ];
   const mtfExpr = px( pairs.map( ( [ om, tm ] ) => Steps.syqonMtfExpression( format( "%.16f", om ), format( "%.16f", tm ) ) ) );
   const invExpr = px( pairs.map( ( [ om, tm ] ) => Steps.syqonInverseMtfExpression( format( "%.16f", om ), format( "%.16f", tm ) ) ) );
   const stretchFormatted = Steps.syqonFormatStretch( [ 0.0123456789, 0.5, 1 / 3, 2 / 3 * 1e-3, 0.00000762939453125 ] );

   const monoPlanes = synth( 300, 200, 1, 0.02, 0.9, 211 );
   const rgbPlanes = synth( 151, 97, 3, 0.03, 0.4, 199 );
   const flatPlanes = synth( 200, 150, 1, 0.5, 0.001, 211 );
   flatPlanes[0][0][0] = 0; // one dark pixel sets the black point; the rest sit at the middle
   const zeroPlanes = synth( 40, 30, 1, 0, 0, 7 );

   const sampleOf = ( planes, stride ) =>
   {
      const img = fakeImage( planes );
      const nch = planes.length >= 3 ? 3 : 1;
      const bg = Steps.prismBackground( img, nch );
      const s = Steps.prismSamples( img, nch, bg.allMin, stride );
      return { bg, s };
   };
   const mono = sampleOf( monoPlanes, 7 );
   const rgb = sampleOf( rgbPlanes, 7 );
   const flat = sampleOf( flatPlanes, 7 );

   const statsAt = [ 0.15, 0.25, 0.4 ].map( T => Steps.prismStretchStats( mono.s.px, mono.bg.x0, T ) );
   const raised = Steps.prismRaisedTarget( flat.s.px, flat.bg.x0, flat.s.p999,
                                           Steps.prismStretchStats( flat.s.px, flat.bg.x0, Steps.PRISM_DEFAULT_TARGET ).std );

   // Forced starting contrast: the raise loop runs from the default target until the highlight cap or the end.
   const raisedLow = Steps.prismRaisedTarget( mono.s.px, mono.bg.x0, mono.s.p999, 0.01 );
   const raisedCapped = Steps.prismRaisedTarget( mono.s.px, mono.bg.x0, 0.99, 0.01 );
   const raisedHigh = Steps.prismRaisedTarget( mono.s.px, mono.bg.x0, mono.s.p999, 0.3 );

   const out = {
      constants: {
         syqon_mtf_target: Steps.SYQON_MTF_TARGET,
         syqon_tile_size: Steps.SYQON_TILE_SIZE,
         syqon_overlap: Steps.SYQON_OVERLAP,
         syqon_pad: Steps.SYQON_PAD,
         syqon_timeout_ms: Steps.SYQON_TIMEOUT_MS,
         prism_default_target: Steps.PRISM_DEFAULT_TARGET,
         prism_corpus_std_min: Steps.PRISM_CORPUS_STD_MIN,
         prism_corpus_std_max: Steps.PRISM_CORPUS_STD_MAX,
         prism_highlight_cap: Steps.PRISM_HIGHLIGHT_CAP,
         prism_target_max: Steps.PRISM_TARGET_MAX
      },
      mtf_midtone_rows: mtfRows,
      mtf_applied: mtfApplied,
      normalise_mins: mins,
      normalise_expression: normalise,
      denormalise_expression: denormalise,
      mtf_expression: mtfExpr,
      inverse_mtf_expression: invExpr,
      format_stretch: stretchFormatted,
      studio_declared_output: declared,
      prism_background_mono: mono.bg,
      prism_background_rgb: rgb.bg,
      prism_samples_mono_count: mono.s.px.length,
      prism_p999_mono: mono.s.p999,
      prism_p999_rgb: rgb.s.p999,
      prism_stretch_stats_mono: statsAt,
      prism_raised_target_flat: raised,
      prism_raised_target_low: raisedLow,
      prism_raised_target_capped: raisedCapped,
      prism_raised_target_high: raisedHigh,
      prism_mtf_target_mono: Steps.prismMtfTarget( win( monoPlanes ), 7 ),
      prism_mtf_target_rgb: Steps.prismMtfTarget( win( rgbPlanes ), 7 ),
      prism_mtf_target_flat: Steps.prismMtfTarget( win( flatPlanes ), 7 ),
      prism_mtf_target_zero: Steps.prismMtfTarget( win( zeroPlanes ), 7 ),
      prism_mtf_target_default_stride: Steps.prismMtfTarget( win( rgbPlanes ) )
   };
   if ( realRect === undefined ) delete globalThis.Rect; else globalThis.Rect = realRect;
   return out;
};
